INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Entgeltformen nur für Festangestellte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Auszubildende"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Entgeltformen?', 3, '[{"text": "Arbeitnehmer vergüten", "correct": true, "because": "Leistung honorieren"}, {"text": "Kosten erhöhen", "correct": false, "because": "Nicht primär"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein technischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entgeltformen gibt es?', 5, '[{"text": "Zeitlohn", "correct": true, "because": "Nach Arbeitszeit"}, {"text": "Leistungslohn", "correct": true, "because": "Nach Ergebnis"}, {"text": "Papierlohn", "correct": false, "because": "Keine Form"}]'),
