('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Entgeltformen?', 4, '[{"text": "Arbeitszeit", "correct": false, "because": "Zeitlohn"}, {"text": "Leistung", "correct": false, "because": "Leistungslohn"}, {"text": "Papierdesign", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Entgeltformen gesetzlich geregelt sind?', 2, '[{"text": "Ja", "correct": true, "because": "Mindestlohn"}, {"text": "Nein", "correct": false, "because": "Regulierung vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entgeltform basiert auf der Arbeitszeit?', 3, '[{"text": "Zeitlohn", "correct": true, "because": "Stundenbasis"}, {"text": "Akkordlohn", "correct": false, "because": "Leistungsbasis"}, {"text": "Prämienlohn", "correct": false, "because": "Zusatzleistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten verschiedene Entgeltformen?', 5, '[{"text": "Motivation durch Leistungslohn", "correct": true, "because": "Leistung belohnen"}, {"text": "Planbarkeit durch Zeitlohn", "correct": true, "because": "Feste Kosten"}, {"text": "Papierersparnis", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Entgeltformen können kombiniert werden. b) Sie sind nur für Vollzeitjobs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Teilzeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Entgeltformen?', 4, '[{"text": "Arbeitsvertrag", "correct": false, "because": "Regelt Entgelt"}, {"text": "Leistungsmessung", "correct": false, "because": "Leistungslohn"}, {"text": "Papierhandbücher", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Zeitlohn leistungsabhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Zeit"}, {"text": "Ja", "correct": false, "because": "Leistung unberücksichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entgeltformen sind leistungsorientiert?', 4, '[{"text": "Akkordlohn", "correct": true, "because": "Produktionsmenge"}, {"text": "Prämienlohn", "correct": true, "because": "Zusatzleistung"}, {"text": "Zeitlohn", "correct": false, "because": "Zeitbasis"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Entgeltformen nur für Angestellte gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Selbstständige"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Entgeltformen?', 3, '[{"text": "Fairness", "correct": true, "because": "Motivation"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Gerechtigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leistungslohn fördert Produktivität. b) Zeitlohn ist immer höher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Höhe variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
